'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const core=require('./pixai-web-queue.user.js');
// Checked-in public fixture is generated by the real app parser/exporter at this HEAD.
// No app repository, TypeScript package, credentials, browser, or DB is needed here.
const fixture=require('./test-fixtures/app-backup-v0.1.18.json');
const copy=value=>JSON.parse(JSON.stringify(value));
const select=(...keys)=>({...core.backupSelection(false),...Object.fromEntries(keys.map(key=>[key,true]))});
const ids=()=>{let n=0;return()=>`import-${++n}`;};
const parse=name=>core.parseTransferBackup(JSON.stringify(fixture.outputs[name]));
const source=()=>copy(fixture.library);
const options={maxCredits:null,filePrefix:'',repeat:1};
const prompts=library=>core.expandPresetReservations(library).map(({prompt,negativePrompt})=>({prompt,negativePrompt}));

test('app fixture records public source identity and actual full/category/folder formats',()=>{
 assert.equal(fixture.provenance.head,'be258addbb29ad0aa171d627db4ac26add950b27');
 assert.match(fixture.provenance.fixtureKind,/public synthetic/);
 assert.equal(fixture.outputs.full.format,'pixai-web-queue-settings');
 assert.equal(fixture.outputs.full.version,1);
 assert.equal(fixture.outputs.category.version,1);
 assert.equal(fixture.outputs.folder.version,2);
 assert.equal(fixture.outputs.sceneFolder.version,2);
});
test('reads actual app full v1, category v1 and folder v2 exports without losing edited scene copies',()=>{
 for(const name of Object.keys(fixture.outputs)){
  const result=parse(name);
  assert.equal(result.format,'pixai-clack-helper-selection');
  assert.deepEqual(result.backup.library,core.normalizePresetLibrary(fixture.outputs[name].backup?.library||fixture.outputs[name].library),name);
 }
 const full=parse('full');assert.deepEqual(prompts(full.backup.library),fixture.expectedPrompts);
 assert.equal(full.backup.options.ui,undefined);
 assert.equal(full.backup.library.sceneCards[0].chunks[0].prompt,'scene-only edited smile');
 assert.equal(full.backup.library.scenes[0].prompt,'live smile');
 assert.deepEqual(parse('folder').folderSelection,{scenes:['f1','f-empty','']});
});
test('folder picker keeps source order and empty folders alongside unfiled counts',()=>{
 assert.deepEqual(core.backupFolderChoices(source(),'scenes'),[
  {id:'f1',name:'합성 표정',count:1},{id:'f2',name:'합성 행동',count:1},
  {id:'f-empty',name:'빈 청크 폴더',count:0},{id:'',name:'미분류',count:1}
 ]);
 assert.deepEqual(core.backupFolderChoices(source(),'sceneCards').map(x=>[x.id,x.count]),[['sf1',1],['sf2',1],['sf-empty',0],['',1]]);
});
test('script category and folder exports match actual app selection output and exclude options by default',()=>{
 const library=source();
 const category=core.makeTransferBackup(library,fixture.options,select('sceneCards'),fixture.meta);
 assert.deepEqual(category,fixture.outputs.category);
 const folder=core.makeTransferBackup(library,fixture.options,select('scenes'),fixture.meta,{scenes:['f1','f-empty','']});
 assert.deepEqual(folder,fixture.outputs.folder);
 assert.deepEqual(folder.backup.options,options);
 assert(!JSON.stringify(folder).includes('synthetic-optional-prefix'));
 const selected=core.selectBackupLibrary(library,select('sceneCards'),{sceneCards:['sf1','sf-empty']});
 assert.deepEqual(selected.dependencies,{scenes:2});
 assert.deepEqual(selected.library.sceneFolders.map(x=>x.id),['sf1','sf-empty']);
 assert.deepEqual(selected.library.scenes.map(x=>x.id),['s1','s2']);
});
test('append keeps same-name and same-ID originals and remaps linked scene/live chunk IDs independently of edited text',()=>{
 const original=source(),before=copy(original),transfer=parse('sceneFolder');
 const result=core.prepareBackupImport(original,transfer,select('sceneCards'),'append',ids());
 assert.deepEqual(original,before);
 assert.deepEqual(result.library.sceneCards.slice(0,3),original.sceneCards);
 assert.deepEqual(result.library.scenes.slice(0,3),original.scenes);
 assert.deepEqual(result.library.sceneFolders.slice(0,3),original.sceneFolders);
 const added=result.library.sceneCards[3],live=result.library.scenes.find(x=>x.id===added.sceneIds[0]);
 assert.notEqual(added.id,'sc1');assert.notEqual(added.folderId,'sf1');assert.notEqual(live.id,'s1');
 assert.equal(live.prompt,'live smile');assert.equal(added.chunks[0].prompt,'scene-only edited smile');
 assert.equal(added.chunks[0].id,live.id);
 assert(result.library.sceneFolders.some(x=>x.id===added.folderId&&x.name==='합성 첫 씬'));
 assert.equal(result.options,undefined);
});
test('category replacement freezes existing legacy reservations and preserves scene snapshots plus unselected materials',()=>{
 const original=source(),before=copy(original),incoming=source();incoming.scenes[0].prompt='replaced live smile';
 const selection=select('scenes');
 const file=core.makeTransferBackup(incoming,options,selection,fixture.meta);
 const result=core.prepareBackupImport(original,file,selection,'replace',ids());
 assert.deepEqual(original,before);
 assert.deepEqual(result.library.characters,original.characters);
 assert.deepEqual(result.library.presets,original.presets);
 assert.deepEqual(result.library.sceneCards,original.sceneCards);
 assert.equal(result.library.scenes[0].prompt,'replaced live smile');
 assert(result.library.reservations.find(x=>x.id==='r-legacy').snapshot);
 assert.deepEqual(prompts(result.library),fixture.expectedPrompts);
 assert.equal(result.library.sceneCards[0].chunks[0].prompt,'scene-only edited smile');
});
test('folder replacement changes only chosen folder/unfiled items and retains other folder order',()=>{
 const original=source(),incoming=source();incoming.scenes[0].prompt='new first';incoming.scenes[2].prompt='new unfiled';
 const selection=select('scenes');
 const file=core.makeTransferBackup(incoming,options,selection,fixture.meta,{scenes:['f1','f-empty','']});
 const result=core.prepareBackupImport(original,file,selection,'replace',ids()).library;
 assert.deepEqual(result.scenes.find(x=>x.id==='s2'),original.scenes[1]);
 assert.equal(result.scenes.find(x=>x.id==='s1').prompt,'new first');
 assert.equal(result.scenes.find(x=>x.id==='s3').prompt,'new unfiled');
 assert.deepEqual(result.chunkFolders,original.chunkFolders);
 assert.deepEqual(result.sceneCards,original.sceneCards);
 assert.deepEqual(prompts(result),fixture.expectedPrompts);
});
test('whole-category replacement adopts the incoming folder order for both chunks and scenes',()=>{
 const original=source(),incoming=source();
 incoming.chunkFolders=[incoming.chunkFolders[2],incoming.chunkFolders[1],incoming.chunkFolders[0]];
 incoming.sceneFolders=[incoming.sceneFolders[1],incoming.sceneFolders[2],incoming.sceneFolders[0]];
 const selection=select('scenes','sceneCards');
 const file=core.makeTransferBackup(incoming,options,selection,fixture.meta);
 assert.equal(file.folderSelection,undefined);
 const result=core.prepareBackupImport(original,file,selection,'replace',ids()).library;
 assert.deepEqual(result.chunkFolders,incoming.chunkFolders);
 assert.deepEqual(result.sceneFolders,incoming.sceneFolders);
 assert.notDeepEqual(result.chunkFolders,original.chunkFolders);
 assert.notDeepEqual(result.sceneFolders,original.sceneFolders);
 assert.deepEqual(result.scenes,incoming.scenes);
 assert.deepEqual(result.sceneCards,incoming.sceneCards);
 assert.deepEqual(prompts(result),fixture.expectedPrompts);
 assert.deepEqual(original,source());
});
test('empty selected folder can be cleared while the folder itself and other groups survive',()=>{
 const original=source();
 const result=core.prepareBackupImport(original,parse('emptyFolder'),select('scenes'),'replace',ids()).library;
 assert.deepEqual(result.scenes,original.scenes.slice(1));
 assert(result.chunkFolders.some(x=>x.id==='f1'));
 assert.deepEqual(result.sceneCards,original.sceneCards);
 assert.deepEqual(prompts(result),fixture.expectedPrompts);
});
test('unfiled-only replacement does not remove named folders and old full files can be narrowed',()=>{
 const original=source(),incoming=parse('full');incoming.backup.library.scenes[2].prompt='changed only unfiled';
 const result=core.prepareBackupImport(original,incoming,select('scenes'),'replace',ids(),{scenes:['']}).library;
 assert.deepEqual(result.scenes.slice(0,2),original.scenes.slice(0,2));
 assert.equal(result.scenes[2].prompt,'changed only unfiled');
 assert.deepEqual(result.chunkFolders,original.chunkFolders);
});
test('retained colliding material IDs are not overwritten when they moved to a different folder',()=>{
 const original=source();original.scenes[0].folderId='f2';
 const file=parse('folder');file.backup.library.scenes[0].prompt='incoming first';
 const result=core.prepareBackupImport(original,file,select('scenes'),'replace',ids()).library;
 assert.deepEqual(result.scenes.find(x=>x.id==='s1'),original.scenes[0]);
 assert.notEqual(result.scenes.find(x=>x.prompt==='incoming first').id,'s1');
});
test('plan/character/cast/common/folder references and reserved final prompts survive an all-material append',()=>{
 const original=source(),selection=select(...Object.keys(core.backupSelection(false)).filter(x=>x!=='options'));
 const imported=core.prepareBackupImport(original,parse('full'),selection,'append',ids()).library;
 assert.deepEqual(prompts(imported).slice(original.reservations.reduce((sum,x)=>sum+x.count,0)),fixture.expectedPrompts);
 const nextPlan=imported.batchPlans[1],cast=imported.casts[1];
 assert.equal(nextPlan.rows[1].id,cast.id);
 assert.equal(nextPlan.exceptions[`cast:${cast.id}|${nextPlan.columns[1]}`],0);
 assert.notEqual(cast.characterId,'c1');assert.notEqual(cast.presetId,'p1');
 const preset=imported.presets.find(x=>x.id===cast.presetId);
 assert.deepEqual(preset.model,original.presets[0].model);assert.deepEqual(preset.loras,original.presets[0].loras);
 assert(imported.commonPresets.some(x=>x.id===preset.commonPresetId));
});
test('options apply only on explicit selection and app UI preferences are converted rather than persisted',()=>{
 const file=parse('full');
 const materials=core.prepareBackupImport(source(),file,select('scenes'),'append',ids());
 assert.equal(materials.options,undefined);
 const explicit=core.prepareBackupImport(source(),file,select('options'),'append',ids());
 assert.equal(explicit.options.repeat,3);assert.equal(explicit.options.imageCount,4);
 assert.equal(explicit.options.ui,undefined);
 assert.deepEqual(explicit.library,source());
});
test('a malformed generation value is refused even when an import will exclude settings',()=>{
 const file=copy(fixture.outputs.full);file.options.api.seed=-1;
 assert.throws(()=>core.parseTransferBackup(JSON.stringify(file)),/seed|시드/);
});
test('category selection may be narrowed but folder exports cannot be widened or given unknown/empty scopes',()=>{
 const library=source(),file=parse('folder');
 for(const folders of [{scenes:[]},{scenes:['f2']},{scenes:['missing']},{scenes:['f1','f1']},{characters:['cf1']}])
  assert.throws(()=>core.prepareBackupImport(library,file,select('scenes'),'replace',ids(),folders));
 assert.throws(()=>core.prepareBackupImport(library,parse('sceneFolder'),select('scenes'),'replace',ids()));
 for(const folders of [{scenes:[]},{scenes:['missing']},{scenes:['f1','f1']},{characters:['cf1']}])
  assert.throws(()=>core.makeTransferBackup(library,options,select('scenes'),fixture.meta,folders));
 assert.throws(()=>core.makeTransferBackup(library,options,select(),fixture.meta));
 assert.throws(()=>core.prepareBackupImport(library,file,select(),'append',ids()));
});
test('rejects invalid envelope/selection/version, unexpected secret fields, and malformed metadata',()=>{
 const valid=fixture.outputs.folder;
 const cases=[null,[],42,{...valid,version:3},{...valid,version:1},{...valid,selection:{scenes:true}},
  {...valid,selection:{...valid.selection,scenes:'true'}},{...valid,token:'synthetic-forbidden'},
  {...valid,folderSelection:{}},{...valid,folderSelection:{scenes:[]}},
  {...valid,folderSelection:{scenes:['missing']}}, {...valid,folderSelection:{scenes:['f1','f1']}}];
 for(const value of cases)assert.throws(()=>core.parseTransferBackup(JSON.stringify(value)));
 const secret=copy(fixture.outputs.full);secret.options.api.apiKey='synthetic-forbidden';assert.throws(()=>core.parseTransferBackup(JSON.stringify(secret)));
 const privateUi=copy(fixture.outputs.full);privateUi.options.ui.apiKey='synthetic-forbidden';assert.throws(()=>core.parseTransferBackup(JSON.stringify(privateUi)));
 const broken=copy(fixture.outputs.full);broken.exportedAt='invalid time';assert.throws(()=>core.parseTransferBackup(JSON.stringify(broken)));
});
test('dangerous object keys are rejected at every envelope depth and prototype is unchanged',()=>{
 const valid=JSON.stringify(fixture.outputs.folder);
 for(const key of ['__proto__','constructor','prototype']){
  for(const text of [valid.replace('{',`{"${key}":{},`),valid.replace('"selection":{',`"selection":{"${key}":{},`),valid.replace('"common":{',`"common":{"${key}":{},`)])
   assert.throws(()=>core.parseTransferBackup(text),key);
 }
 assert.equal({}.polluted,undefined);
});
test('files over 5MiB are refused by characters or UTF-8 byte length',()=>{
 assert.throws(()=>core.parseTransferBackup(' '.repeat(5*1024*1024+1)),/5MiB/);
 const large=copy(fixture.outputs.folder);large.backup.appVersion='가'.repeat(2*1024*1024);
 assert.throws(()=>core.parseTransferBackup(JSON.stringify(large)),/5MiB/);
});
test('failed import ID allocation and invalid linked-set replacement do not mutate originals',()=>{
 const original=source(),before=copy(original);
 assert.throws(()=>core.prepareBackupImport(original,parse('sceneFolder'),select('sceneCards'),'append',()=>'sc1'),/ID/);
 const incoming=copy(fixture.outputs.full);incoming.library.commonPresets=[];
 delete incoming.library.presets[0].commonPresetId;
 const file=core.parseTransferBackup(JSON.stringify(incoming));
 assert.throws(()=>core.prepareBackupImport(original,file,select('commonPresets'),'replace',ids()),/프리셋/);
 assert.deepEqual(original,before);
});
test('app-compatible full exports preserve final reservation prompts through a script re-import',()=>{
 const library=parse('full').backup.library;
 const file=core.compatibleSettings(library,{...options,embedMetadata:true},fixture.meta,'app').backup;
 assert.equal(file.version,1);assert.equal(file.options.embedMetadata,undefined);
 assert.deepEqual(prompts(core.parseSettingsBackup(JSON.stringify(file)).library),fixture.expectedPrompts);
 assert.deepEqual(file.library.sceneCards,library.sceneCards);
});
